        bid = DAILY_SALARY * 0.18
        return max(0.0, min(budget, bid))

    if comfortable_supply:
        bid = DAILY_SALARY * 0.28
        return max(0.0, min(budget, bid))

    if tight_supply:
        if eric_prev >= 140:
            bid = eric_prev + 2.5
        else:
            bid = max(DAILY_SALARY * 0.9, pressure + 2.0)
        return max(0.0, min(budget, bid))

    if eric_prev >= 160:
        bid = DAILY_SALARY * 0.35
    elif eric_prev >= 120:
        bid = DAILY_SALARY * 0.48
    else:
