def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday's bids for immediate reaction
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline: need enough to stay alive; higher when supply is low or hp is low.
    # Medium scenario supply is between 15 and 25; if supply is closer to 15, competition is tighter.
    supply_factor = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_factor = max(0.0, min(1.0, supply_factor))

    # Pressure estimate from yesterday (Eric likely highest bidder)
    if prev_bids:
        highest_prev_bid = max(prev_bids)
    else:
        highest_prev_bid = 0.0

    # If someone previously bid very high, we slightly counter with a controlled overbid.
    # Otherwise bid around a mid level to secure water.
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        # We don't know today's hidden bids; bid just enough to contest without draining budget.
        target = min(budget, DAILY_SALARY * (0.45 + 0.25 * supply_factor))
        # If our hp is critical, increase urgency.
        if hp <= 3 or no_water_days >= 1:
            target = min(budget, DAILY_SALARY * (0.75 + 0.15 * supply_factor))
        # Mildly tie to opponent pressure
        target = max(target, min(budget, highest_prev_bid * 0.65))
    else:
        target = DAILY_SALARY * (0.35 + 0.25 * supply_factor)
        if hp <= 3 or no_water_days >= 1:
            target = DAILY_SALARY * (0.65 + 0.2 * supply_factor)
        target = min(budget, target)

    # Ensure non-negative and reasonable cap.
    if budget <= 0.0:
        return 0.0
    bid = max(0.0, min(budget, target))

    # If supply is extremely low relative to requirement, be more aggressive.
    # (In this scenario supply is >=15 so still manageable.)
    if supply < WATER_REQ + 1:
        bid = min(budget, max(bid, DAILY_SALARY * 0.7))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = int(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Estimate opponents' bids from previous trace
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Base bid strategy
    if my_status['hp'] <= 2:
        # Desperate: bid high to ensure water
        bid = min(my_status['budget'], DAILY_SALARY * 0.9)
    elif my_status['hp'] <= 4:
        # Moderate risk: bid slightly above average of previous bids if any, else conservative
        if prev_bids:
            avg_prev = sum(prev_bids) / len(prev_bids)
            bid = min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev * 0.8))
        else:
            bid = min(my_status['budget'], DAILY_SALARY * 0.5)
    else:
        # Healthy: try to save money
        if prev_bids:
            avg_prev = sum(prev_bids) / len(prev_bids)
            # Bid just under average to possibly win with less
            bid = min(my_status['budget'], max(DAILY_SALARY * 0.3, avg_prev * 0.7))
        else:
            bid = min(my_status['budget'], DAILY_SALARY * 0.35)

    # Ensure bid is non-negative and not more than budget
    bid = max(0, bid)
    bid = min(bid, my_status['budget'])
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    TOTAL_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # 1. If no opponents, bid low to save budget
    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    # 2. If my HP is critically low, bid very high to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # 3. Analyze yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # 4. Decision logic based on yesterday's highest pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If highest bid was very aggressive (e.g., trying to eliminate others)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # My HP is good, I can afford to back off and let others overspend
                return min(my_status['budget'], DAILY_SALARY * 0.35)
            else: # My HP is not good, I must compete aggressively
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:
            # Highest bid was moderate, try to outbid it slightly but ensure a base competitive bid
            return min(my_status['budget'], max(DAILY_SALARY * 0.55, highest_prev_bid + 2.5))

    # 5. If no yesterday bids (e.g., first day or all opponents were inactive/died)
    # Use a default strategy based on my HP and day context
    current_day = day_context['day']

    if my_status['hp'] <= 3: # Low HP, need water
        return min(my_status['budget'], DAILY_SALARY * 0.8)
    elif current_day >= TOTAL_DAYS - 2: # Late game (last 2 days), be more aggressive to secure survival
        return min(my_status['budget'], DAILY_SALARY * 0.75)
    else: # Default for good HP and early/mid game
        return min(my_status['budget'], DAILY_SALARY * 0.65)
